import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788357264000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>All eight are registered unless you say otherwise. <code>RUSTPAD_ALLOW_TOOLS</code> and <code>RUSTPAD_DENY_TOOLS</code> narrow the list to the ones you want, and <code>essential</code> selects a curated five — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Eight tools. <code>id</code> is always the pad id — the part after <code>#</code> in a pad&#39;s URL, restricted to letters, digits, dot, underscore and hyphen. All results that contain pad-derived text carry the untrusted-content marker.</p><p>With <code>RUSTPAD_READ_ONLY=true</code> only the three read tools are registered.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose — the five write tools used to answer with a sentence, and the sentence is still in the text block. <code>get_document</code> answers <code>{text}</code> rather than the pad itself: a schema whose root is a string is served to a 2025-era client rewritten as <code>{result: …}</code>, and <code>empty</code> and <code>truncated</code> need somewhere to live either way.</p><p>The two read tools that report pad content carry <code>untrusted: true</code> and <code>source: &quot;rustpad&quot;</code> as fields of the object, so the marker is something a client can check rather than prose it has to notice.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — where the client cannot show a dialog it falls back to a two-call <code>confirm_token</code>. <code>ELICITATION=false</code> takes that fallback deliberately. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. The three reads are <code>readOnlyHint: true</code>; <code>set_document</code> and <code>replace_in_document</code> are the two marked <code>destructiveHint: true</code>; <code>openWorldHint</code> is <code>false</code> throughout, because this server talks to the one Rustpad it is configured for.</p><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to “Read”">​</a></h2><h3 id="get-document" tabindex="-1">get_document <a class="header-anchor" href="#get-document" aria-label="Permalink to “get_document”">​</a></h3><p>Reads the current plain-text content of a pad over HTTP.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr></tbody></table><p>An empty result is ambiguous — Rustpad reports an empty pad, a pad that never existed and an expired pad identically, and the result says so.</p><h3 id="get-document-info" tabindex="-1">get_document_info <a class="header-anchor" href="#get-document-info" aria-label="Permalink to “get_document_info”">​</a></h3><p>Connects to the collaboration socket and reports metadata.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr></tbody></table><p>Returns the pad&#39;s URL, content length in characters, revision number, editor language and the display names of everyone who has the pad open right now.</p><h3 id="get-stats" tabindex="-1">get_stats <a class="header-anchor" href="#get-stats" aria-label="Permalink to “get_stats”">​</a></h3><p>No parameters. Server statistics: start time (raw and ISO), number of documents currently in memory, number persisted in the database (0 without <code>SQLITE_URI</code>).</p><h2 id="write" tabindex="-1">Write <a class="header-anchor" href="#write" aria-label="Permalink to “Write”">​</a></h2><h3 id="create-document" tabindex="-1">create_document <a class="header-anchor" href="#create-document" aria-label="Permalink to “create_document”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>no</td><td>Desired pad id; omitted → a random one</td></tr><tr><td><code>text</code></td><td>string</td><td>no</td><td>Initial content (≤ 256 KiB)</td></tr><tr><td><code>language</code></td><td>string</td><td>no</td><td>Monaco language id, e.g. <code>markdown</code></td></tr></tbody></table><p>Fails if the pad already has content — use <code>set_document</code> or <code>append_to_document</code> for that. Returns the shareable URL.</p><h3 id="set-document-👤" tabindex="-1">set_document 👤 <a class="header-anchor" href="#set-document-👤" aria-label="Permalink to “set_document 👤”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr><tr><td><code>text</code></td><td>string</td><td>yes</td><td>Full replacement content (≤ 256 KiB)</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, second call only</td></tr></tbody></table><p>Replaces the entire pad. <strong>Replacing a non-empty pad asks a person first</strong> — a dialog the model cannot answer on its behalf. Where the client cannot show one, the first call returns a single-use token bound to the pad and the exact replacement text, and the second call with that token executes. Writing an empty pad asks nothing: there is nothing to lose.</p><h3 id="append-to-document" tabindex="-1">append_to_document <a class="header-anchor" href="#append-to-document" aria-label="Permalink to “append_to_document”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr><tr><td><code>text</code></td><td>string</td><td>yes</td><td>Text to append verbatim</td></tr></tbody></table><p>Appends at the end; everything else — including edits other collaborators make at the same moment — is retained. Include a leading <code>\\n</code> to start a new line.</p><h3 id="replace-in-document-👤" tabindex="-1">replace_in_document 👤 <a class="header-anchor" href="#replace-in-document-👤" aria-label="Permalink to “replace_in_document 👤”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr><tr><td><code>search</code></td><td>string</td><td>yes</td><td>Exact string to find (no regex)</td></tr><tr><td><code>replace</code></td><td>string</td><td>yes</td><td>Replacement; may be empty to delete the match</td></tr><tr><td><code>replace_all</code></td><td>boolean</td><td>no</td><td>Replace every occurrence (default: unique match)</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, second call only</td></tr></tbody></table><p>Only the matched ranges are edited, so concurrent edits elsewhere survive. By default the search string must occur exactly once; otherwise the error reports the count and suggests a longer search string or <code>replace_all</code>.</p><p><strong>Asks a person when it is about to change more than one place.</strong> A single, unique replacement goes straight through — that is what the tool is for, and a dialog on every one of them is how people learn to tick without reading. The line is drawn on the count rather than on the flag, because the count is the mistake worth catching: a search string that is shorter than intended matches where nobody looked. The number in the prompt is measured inside the open session, so it describes the pad as it stands.</p><h3 id="set-language" tabindex="-1">set_language <a class="header-anchor" href="#set-language" aria-label="Permalink to “set_language”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Pad id</td></tr><tr><td><code>language</code></td><td>string</td><td>yes</td><td>Monaco language id, e.g. <code>rust</code></td></tr></tbody></table><p>Sets the syntax-highlighting language for everyone; last writer wins.</p>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};